/* 统一管理层。索引现有库，候选与采用仍保存在原工作台，不迁移旧记录。 */
(()=>{
  const C=Cimora,S=Site,L=StudioLibraryModel,E=S.esc,copy=value=>JSON.parse(JSON.stringify(value));
  const KEY='cimora-studio-library-v1',STORY='cimora-script-studio-v1',COMIC='cimora-comic-studio-v1';
  let selectingAssets=false,selectedAssets=new Set();
  let warnings=[],view={projectType:'all',projectState:'active',projectSearch:'',assetType:'全部',assetSource:'all',assetProject:'all',assetTags:'',assetSearch:'',assetState:'active',onlyExamples:false};
  const q=value=>encodeURIComponent(value),a=(text,url,cls='ghost')=>C.link(text,url,'cm-button '+cls);
  const b=(text,act,key='',cls='ghost')=>`<button type="button" class="cm-button ${cls}" data-lib="${act}" data-key="${E(key)}">${text}</button>`;
  const tags=value=>`<span class="sl-tag">${E(value)}</span>`;
  const imageLabel=slot=>({main:'主参考',sheet:'角色设定表',portrait:'头像',front:'正面',side:'侧面',back:'背面',clothing:'服装参考',accessories:'配饰',first:'首帧',last:'尾帧',idle:'待机',speaking:'说话',blink:'眨眼','blink-speaking':'说话与眨眼'})[slot]||(/expression/.test(slot)?'表情参考':/pose/.test(slot)?'姿势参考':'参考图');
  const types=L.categories;
  function read(key,fallback){const raw=localStorage.getItem(key);if(!raw)return copy(fallback);const value=JSON.parse(raw);if(!value||typeof value!=='object')throw Error('保存记录格式异常，已保留原记录。');return value;}
  function meta(){const raw=StudioManagementStorage.read(),value=raw?JSON.parse(raw):{version:1,projects:{},assets:{},personal:[],examples:null};if(value.version!==1||!value.projects||!value.assets||!Array.isArray(value.personal))throw Error('管理记录无法读取，请保留浏览器数据。');return value;}
  function store(key,value){if(key===KEY)return StudioManagementStorage.write(value);try{localStorage.setItem(key,JSON.stringify(value));}catch{throw Error('本机空间不足，未保存本次修改。');}}
  function changeMeta(fn){return StudioManagementStorage.change(value=>{if(value.version!==1||!value.projects||!value.assets||!Array.isArray(value.personal))throw Error('管理记录无法读取，请保留浏览器数据。');fn(value);});}
  function load(){
    warnings=[];const safely=(name,fn,fallback)=>{try{return fn();}catch(error){warnings.push(name+'：'+error.message);return fallback;}};
    const management=safely('管理记录',meta,{projects:{},assets:{},personal:[]});
    const stories=safely('故事库',()=>{const value=read(STORY,{projects:[],assets:[]});if(!Array.isArray(value.projects)||!Array.isArray(value.assets))throw Error('记录格式异常');return value;},{projects:[],assets:[]});
    const comics=safely('漫画库',()=>{const value=read(COMIC,{projects:[]});if(!Array.isArray(value.projects))throw Error('记录格式异常');return value;},{projects:[]});
    const videoEntries=[];for(const project of S.state.projects){for(const [hostId,engine] of Object.entries(C.M.db.projects[project.id]||{})){const workspace=engine.videoFlow?.workspace;if(workspace)videoEntries.push({projectId:project.id,hostId,workspace,source:engine.videoFlow.source,shots:engine.productionShots||[],bindings:engine.bindings,createdAt:engine.videoFlow.createdAt,engine});}}
    const result=L.build({stories,comics,videos:S.state.projects,videoEntries,legacyAssets:S.state.assets,tools:safely('工具成果',()=>ToolStudio.store.list(),[]),meta:management});
    for(const personal of management.personal){const owner=result.projects.find(p=>p.key===personal.owner);result.assets.push({...personal,ownerName:owner?.title||personal.ownerName||'个人资产',state:management.assets[personal.key]?.state||'active',usages:personal.usages||[]});}
    for(const asset of result.assets){const link=asset.version?.librarySource,source=link&&result.assets.find(item=>item.key===link.assetKey);if(source){asset.sourceAssetKey=source.key;asset.sourceUpdated=!!source.version&&source.version.id!==link.versionId;}}
    for(const asset of result.assets){for(const version of asset.versions||[]){const origin=version.librarySource;if(!origin)continue;const source=result.assets.find(item=>item.key===origin.assetKey);if(source&&!source.usages.some(use=>use.projectKey===asset.owner&&use.assetKey===asset.key&&use.versionId===origin.versionId))source.usages.push({projectKey:asset.owner,assetKey:asset.key,label:asset.ownerName,versionId:origin.versionId,candidate:asset.version?.id!==version.id});}}
    for(const project of result.projects){
      const references=project.kind==='video'?(project.entries||[]).flatMap(entry=>entry.workspace.planningReferences||[]):project.raw.planningReferences||[];
      for(const reference of references){const source=result.assets.find(asset=>asset.key===reference.assetKey);if(source&&!source.usages.some(use=>use.projectKey===project.key&&use.versionId===reference.versionId))source.usages.push({projectKey:project.key,label:project.title+' · 内容策划',versionId:reference.versionId});}
      if(project.kind!=='video')continue;
      for(const entry of project.entries)for(const [episodeId,episode] of Object.entries(entry.workspace.finishing?.episodes||{})){
        const library=episode.audioLibrary||{};
        for(const candidate of [...(library.music||[]),...Object.values(library.voices||{}).flat(),...Object.values(library.effects||{}).flat()]){
          const source=result.assets.find(asset=>asset.key===candidate.librarySource?.assetKey);if(!source)continue;
          const adopted=episode.musicAdoptedId===candidate.id||Object.values(episode.sounds||{}).some(sound=>sound.task?.id===candidate.id)||Object.values(episode.effectAdopted||{}).some(categories=>Object.values(categories).includes(candidate.id));
          const usageKey=project.key+':sound:'+entry.hostId+':'+episodeId+':'+candidate.id;
          if(!source.usages.some(use=>use.projectKey===project.key&&use.assetKey===usageKey))source.usages.push({projectKey:project.key,assetKey:usageKey,label:project.title,versionId:candidate.librarySource.versionId,candidate:!adopted});
        }
      }
    }
    for(const asset of result.assets)asset.tags=(management.assets[asset.key]?.tags||[]).filter(id=>(management.tags||[]).some(tag=>tag.id===id));
    result.meta=management;return result;
  }
  const warning=()=>warnings.length?`<p class="sl-warning" role="alert">${warnings.map(E).join('<br>')}。未覆盖相关记录，写入操作已暂停。</p>`:'';
  const guard=()=>{load();if(warnings.length)throw Error('存在无法读取的记录，已暂停写入，原数据保留。');};
  const heading=(title,desc,actions='')=>`<header class="sl-heading"><div><span class="cm-kicker">MY CREATIVE STUDIO</span><h1>${title}</h1><p>${desc}</p></div><div class="sl-actions">${actions}</div></header>`;
  const findProject=key=>load().projects.find(project=>project.key===key),findAsset=key=>load().assets.find(asset=>asset.key===key);
  const projectURL=project=>'/app/projects?item='+q(project.key);
  const assetURL=asset=>'/app/assets?item='+q(asset.key);
  const localPath=path=>typeof path==='string'&&/^\/app\/(?:projects|assets|tool-results|market|creator|wallet)(?:[/?]|$)/.test(path)&&path.length<12000?path:'';
  const withBack=path=>path+(path.includes('?')?'&':'?')+'back='+q(localPath(location.hash.slice(1))||'/app/projects');
  const backLink=fallback=>a('← 返回',localPath(S.context.params.get('back'))||fallback,'sl-back');
  const scrollPositions=new Map(),workbenchReturns=new Map();
  function filterURL(){const path=S.context.parts[1]==='projects'?'/app/projects':'/app/assets',params=new URLSearchParams(location.hash.split('?')[1]||'');
    const fields=path.endsWith('projects')?['projectType','projectState','projectSearch','onlyExamples']:['assetType','assetTags','assetState','assetSource','assetProject','assetSearch'];
    for(const field of fields)params.set(field,String(view[field]));params.delete('type');params.delete('project');params.delete('source');params.delete('assetSubtype');return path+'?'+params;}
  function hydrateView(ctx,fields){const defaults={projectType:'all',projectState:'active',projectSearch:'',onlyExamples:false,assetType:'全部',assetState:'active',assetSource:'all',assetProject:'all',assetTags:'',assetSearch:''};for(const field of fields)view[field]=ctx.params.has(field)?(field==='onlyExamples'?ctx.params.get(field)==='true':ctx.params.get(field)):defaults[field];}
  function reusable(asset){if(!asset||asset.state!=='active'||asset.placeholder)return false;if(asset.raw?.market&&asset.type==='声音')return !!asset.raw.audio&&['voiceover','background-music','sound-effects'].includes(asset.raw.toolId);if(asset.tool&&asset.key.startsWith('tool:'))return !['live2d-generation','sticker-maker'].includes(asset.raw.toolId)&&(!['pngtuber'].includes(asset.raw.toolId)||['comic','video'].includes(asset.raw.character?.source?.scope));return eligible(asset);}
  function heroImage(project,index){const asset=index.assets.find(asset=>asset.owner===project.key&&asset.image);return asset?`<img src="${E(asset.image)}" alt="${E(asset.name)}" loading="lazy">`:`<span class="sl-project-symbol">${{story:'文',comic:'▦',video:'▷'}[project.kind]}</span>`;}
  function projectCard(project,index){return `<article class="sl-project-card"><a class="sl-project-picture ${project.kind}" href="#${projectURL(project)}">${heroImage(project,index)}<span>${L.labels[project.kind]}${project.example?' · 示例':''}</span></a><div class="sl-card-copy"><h3><a href="#${projectURL(project)}">${E(project.title)}</a></h3><p>${E(project.description)}</p><strong class="sl-progress">${E(project.progress)}</strong><div class="sl-card-meta">${tags(project.stage)}<small>${project.related.length?'关联 '+project.related.length+' 个作品':'独立工程'}</small></div><footer>${a('继续创作 ↗',project.url,'primary')}${a('管理',projectURL(project))}</footer></div></article>`;}
  function examplesBanner(index){const present=index.meta.examples;return `<section class="sl-example-banner"><div><span class="sl-example-dot">✦</span><div><strong>试一次完整的管理流程</strong><p>故事 → 漫画 → 视频关联，角色候选与采用，工具成果复用。视频、声音为说明占位。</p></div></div><div class="sl-actions">${present?b(view.onlyExamples?'显示所有项目':'只看管理示例','toggle-examples'):b('载入简单示例','examples','','primary')}${present?a('查看操作指引','/app/projects?guide=1'):''}</div></section>`;}
  function projects(ctx){const index=load(),wanted=ctx.params.get('item');if(wanted)return projectDetail(index.projects.find(p=>p.key===wanted),index);if(ctx.parts[2]){const existing=index.projects.find(p=>p.id===ctx.parts[2]);return existing?projectDetail(existing,index):oldRoute({...ctx,params:new URLSearchParams('legacy=1')});}hydrateView(ctx,['projectType','projectState','projectSearch','onlyExamples']);
    const list=index.projects.filter(project=>project.state===view.projectState&&(view.projectType==='all'||project.kind===view.projectType)&&(!view.onlyExamples||project.example)&&(!view.projectSearch||(project.title+' '+project.description).toLowerCase().includes(view.projectSearch.toLowerCase()))).sort((x,y)=>String(y.updated).localeCompare(String(x.updated)));
    return `<div class="sl-page">${heading('我的项目','找到正在做的作品，从上次的位置继续。',b('＋ 创建项目','create-project'))}${warning()}${examplesBanner(index)}${ctx.params.has('guide')?guide(index):''}<div class="sl-toolbar"><div class="sl-tabs" role="group" aria-label="项目类型">${[['all','全部'],['story','故事'],['comic','漫画'],['video','视频']].map(([key,title])=>b(title,'project-type',key,view.projectType===key?'selected':'ghost')).join('')}</div><div class="sl-actions"><label class="sl-search">⌕<input data-lib-search="projectSearch" aria-label="搜索项目" placeholder="搜索项目名称或内容" value="${E(view.projectSearch)}"></label><select data-lib-filter="projectState" aria-label="项目状态"><option value="active" ${view.projectState==='active'?'selected':''}>进行中</option><option value="archived" ${view.projectState==='archived'?'selected':''}>已归档</option><option value="trash" ${view.projectState==='trash'?'selected':''}>回收站</option></select></div></div><p class="sl-count">${list.length} 个${view.projectState==='trash'?'已回收':view.projectState==='archived'?'归档':'进行中'}工程${view.onlyExamples?' · 仅管理示例':''}</p><div class="sl-project-grid">${list.map(project=>projectCard(project,index)).join('')||empty('这里还没有项目','创建故事、漫画或视频，或载入上方示例体验。')}</div>${view.projectState==='trash'?'<p class="sl-footnote">回收站保留工程和素材，可随时恢复。关联作品和已复用的资产不受影响。</p>':''}</div>`;
  }
  function guide(index){const ids=index.meta.examples;if(!ids)return '';const project=index.projects.find(p=>p.key===ids.comic),asset=index.assets.find(a=>a.owner===ids.comic&&a.name==='陆川'),tool=index.assets.find(a=>a.key===ids.outfit);return `<section class="sl-guide"><h2>三个简单操作</h2><div><article><b>01 · 看作品如何关联</b><p>故事保留原稿，漫画选用前两集，视频再继承漫画的人物和内容。</p>${project?a('查看漫画工程',projectURL(project)):''}</article><article><b>02 · 把角色带入视频</b><p>打开陆川 → 用于作品 → 选择视频中的人物 → 新增候选 → 确认采用。原漫画不变。</p>${asset?a('打开陆川资产',assetURL(asset)):''}</article><article><b>03 · 复用工具成果</b><p>把保存的服饰参考带入漫画陆川，作为候选；采用或切回原版本，观察使用位置。</p>${tool?a('打开服饰参考',assetURL(tool)):''}</article></div></section>`;}
  function empty(title,desc){return `<div class="sl-empty"><span>◈</span><h2>${title}</h2><p>${desc}</p></div>`;}
  function sourceName(project,index){if(!project.source)return '直接创作';const parent=index.projects.find(p=>project.related.includes(p.key)&&p.id===project.source.projectId);return parent?.title||project.source.title||'已保存来源';}
  function projectDetail(project,index){if(!project)return `<div class="sl-page">${empty('未找到这个工程','原有工程不受影响，可返回列表查找。')}${a('返回我的项目','/app/projects')}</div>`;
    const assets=index.assets.filter(asset=>asset.owner===project.key),source=project.source,related=project.related.map(key=>index.projects.find(p=>p.key===key)).filter(Boolean),p=project.raw;
    const original=p.original||source?.original||p.text||'';
    const adopted=assets.filter(asset=>asset.version&&!asset.placeholder).length,pending=assets.filter(asset=>asset.versions?.length&&!asset.version).length;
    return `<div class="sl-page">${backLink('/app/projects')}${heading(E(project.title),L.labels[project.kind]+'工程 · '+project.stage,a('继续创作 ↗',project.url,'primary')+b('重命名','rename-project',project.key))}${warning()}${project.state!=='active'?`<p class="sl-warning">此工程${project.state==='trash'?'已在回收站':'已归档'}。${b('恢复到进行中','restore-project',project.key)}</p>`:''}<div class="sl-detail-grid"><div><section class="sl-panel"><h2>创作进度</h2><p class="sl-large-progress">${E(project.progress)}</p><p>${E(project.description.length>180?project.description.slice(0,180)+"…":project.description)}</p>${project.description.length>180?"<details><summary>展开内容简介</summary><pre>"+E(project.description)+"</pre></details>":""}<div class="sl-episode-list">${project.episodes.map((ep,i)=>`<div><span>${i+1}</span><div><strong>${E(ep.title||'第'+(i+1)+'集')}</strong><p>${E((ep.events||ep.outline||ep.summary||ep.text||'在工作台继续整理本集内容').slice(0,160))}${(ep.events||ep.outline||ep.summary||ep.text||'').length>160?'…':''}</p></div></div>`).join('')||'<p>尚未整理分集，可继续进入工作台创作。</p>'}</div></section><section class="sl-panel"><header><h2>项目资产</h2>${a('查看全部 '+assets.length+' 项','/app/assets?project='+q(project.key))}</header><p>已采用 ${adopted} 项 · 待采用 ${pending} 项。候选和历史版本在资产详情内查看。</p><div class="sl-mini-assets">${assets.slice(0,6).map(asset=>`<a href="#${assetURL(asset)}"><span>${asset.image?`<img src="${E(asset.image)}" alt="${E(asset.name)}">`:'◈'}</span><strong>${E(asset.name)}</strong><small>${E(asset.type)}</small></a>`).join('')||'<p>尚无资产。在创作工作台准备，或从资产库选用。</p>'}</div></section><section class="sl-panel"><h2>成品</h2><p>${project.example&&project.kind==='video'?'视频占位：这里会收纳本工程各集的已合成视频、封面和导出版本。本示例不包含可播放视频。':'已采用的漫画成稿页和工作台交付版本在对应作品内管理。'}</p>${a('进入作品查看',project.url)}</section></div><aside><section class="sl-panel"><h2>来源与关联作品</h2><p>来源：${E(sourceName(project,index))}</p>${source?`<p>选用范围：${source.episodeIds?.length?source.episodeIds.length+'集':'独立保存的来源内容'}</p><p class="sl-footnote">使用创建时的版本。上游修改不自动覆盖当前作品。</p>`:''}${related.map(item=>`<a class="sl-related" href="#${projectURL(item)}"><span>${L.labels[item.kind]}</span><div><b>${E(item.title)}</b><small>${E(item.progress)}</small></div><b>↗</b></a>`).join('')||'<p class="sl-footnote">尚无关联作品。通过选用故事或漫画创作后，自动记录关系。</p>'}</section><section class="sl-panel"><h2>来源材料</h2><details><summary>查看保留的原始内容</summary><pre>${E(original||'此工程尚未登记原始材料。')}</pre></details><p class="sl-footnote">原文独立保留，摘要和改编稿不会替代来源。</p></section><section class="sl-panel"><h2>工程管理</h2>${project.state==='active'?b('归档项目','archive-project',project.key):b('恢复到进行中','restore-project',project.key)}${project.state!=='trash'?b('移入回收站','trash-project',project.key):''}<p class="sl-footnote">只管理当前工程；关联作品和已采用素材保留。</p></section></aside></div></div>`;
  }
  const sourceLabel=asset=>L.sourceLabels[L.creationSource(asset)];
  function assetTagChips(asset){const tags=meta().tags||[];return asset.tags?.length?`<div class="sl-tag-chips">${asset.tags.map(id=>tags.find(tag=>tag.id===id)).filter(Boolean).map(tag=>`<span class="sl-user-tag">${E(tag.name)}</span>`).join('')}</div>`:'';}
  function tagFilters(index){
    const selected=view.assetTags.split(',').filter(Boolean),available=index.meta.tags||[];
    return `<section class="sl-tag-filter"><div><span>我的标签</span>${b('全部','filter-tag','all',!selected.length?'selected':'ghost')}${b('未添加标签','filter-tag','untagged',selected.includes('untagged')?'selected':'ghost')}${available.map(tag=>b(E(tag.name),'filter-tag',tag.id,selected.includes(tag.id)?'selected':'ghost')).join('')}${b('管理标签','manage-tags','','sl-tag-manage')}</div><small>${selected.length>1?'同时包含所选的 '+selected.length+' 个标签':available.length?'可多选标签，同时匹配':'添加自己的标签，方便跨类型整理素材；也可以先直接保存。'}</small></section>`;
  }
  function bulkTagBar(list){return `<div class="sl-bulk-bar">${b(selectingAssets?'完成整理':'批量整理','toggle-bulk')}${selectingAssets?`<span id="sl-selected-count">已选择 ${selectedAssets.size} 项</span>${b('全选本次结果','select-visible')}${b('清空选择','clear-selection')}${b('添加标签','bulk-add-tags').replace('<button ','<button '+(!selectedAssets.size?'disabled ':''))}${b('移除标签','bulk-remove-tags').replace('<button ','<button '+(!selectedAssets.size?'disabled ':''))}`:''}</div>`;}
  let tagEdit=null;
  function mutateTags(transform){guard();return changeMeta(value=>{const next=transform(value);Object.assign(value,next);});}
  function tagEditor(keys,mode){
    const index=load(),assets=keys.map(key=>index.assets.find(asset=>asset.key===key)).filter(Boolean);
    if(assets.length!==keys.length)throw Error('部分资产已不存在，请刷新后重试');
    tagEdit={keys,mode};const current=mode==='replace'?assets[0].tags:[],tags=index.meta.tags||[];
    S.modal(mode==='replace'?'编辑资产标签':mode==='add'?'批量添加标签':'批量移除标签',`<p>${mode==='replace'?'管理这份成果的标签，具体成果类型和项目引用保持原状。':`为所选 ${keys.length} 项资产${mode==='add'?'添加':'移除'}相同标签，其他标签保留。`}</p><div class="sl-tag-options">${tags.map(tag=>`<label><input type="checkbox" data-lib-tag-option="${E(tag.id)}" ${current.includes(tag.id)?'checked':''}>${E(tag.name)}</label>`).join('')||'<p>还没有标签，输入名称即可创建。</p>'}</div>${mode!=='remove'?'<label>创建新标签（可选）<input id="sl-inline-tag" maxlength="30" placeholder="例如：我的 OC、雨夜、直播用"></label>':''}<p class="sl-footnote">标签在整个资产库通用；无需为每份成果添加。</p>`,b('保存标签','save-tags','','primary'));
  }
  async function saveTagEditor(){
    if(!tagEdit)throw Error('请重新打开标签编辑');
    const {keys,mode}=tagEdit,ids=[...document.querySelectorAll('[data-lib-tag-option]:checked')].map(node=>node.dataset.libTagOption),name=document.getElementById('sl-inline-tag')?.value.trim();
    await mutateTags(value=>{let next=value;if(name){const existing=(value.tags||[]).find(tag=>tag.name.toLowerCase()===name.replace(/\s+/g,' ').normalize('NFC').toLowerCase());const id=existing?.id||S.id('tag');if(!existing)next=L.createTag(next,id,name);ids.push(id);}return L.assignTags(next,keys,ids,mode);});
    tagEdit=null;S.close();S.render();S.toast('标签已保存，资产内容和项目引用保留');
  }
  function tagManager(){
    const index=load(),tags=index.meta.tags||[];
    S.modal('管理我的标签',`<p>标签全资产库通用。改名、合并或删除标签都不会删除资产。</p><div class="sl-tag-management">${tags.map(tag=>`<div><strong>${E(tag.name)}</strong><small>${index.assets.filter(asset=>asset.tags.includes(tag.id)).length} 项资产</small><div>${b('改名','rename-tag',tag.id)}${tags.length>1?b('合并','merge-tag',tag.id):''}${b('删除','delete-tag',tag.id)}</div></div>`).join('')||'<p>还没有自定义标签。</p>'}</div><label>新标签<input id="sl-new-tag" maxlength="30" placeholder="输入标签名称"></label>`,b('创建标签','create-tag','','primary'));
  }
  function tagRename(id){const tag=(meta().tags||[]).find(tag=>tag.id===id);if(!tag)throw Error('标签不存在');S.modal('重命名标签',`<label>标签名称<input id="sl-tag-name" maxlength="30" value="${E(tag.name)}"></label>`,b('保存名称','confirm-rename-tag',id,'primary'));}
  function tagMerge(id){const tags=meta().tags||[],tag=tags.find(tag=>tag.id===id);if(!tag)throw Error('标签不存在');S.modal('合并标签',`<p>将「${E(tag.name)}」合并到另一个标签，原有资产标记会统一更新。</p><label>合并到<select id="sl-merge-target">${tags.filter(tag=>tag.id!==id).map(tag=>`<option value="${E(tag.id)}">${E(tag.name)}</option>`).join('')}</select></label>`,b('确认合并','confirm-merge-tag',id,'primary'));}
  function toolActions(asset){return asset.tool&&asset.key.startsWith('tool:')?b(asset.type==='声音'?'试听 / 下载':'查看成果 / 下载','open-tool-result',asset.id,'primary'):'';}
  function assetCard(asset){
    const projects=L.projectKeys(asset),pendingOnly=!asset.owner&&asset.usages.length&&asset.usages.every(use=>use.candidate);
    return `<article class="sl-asset-card">${selectingAssets?`<label class="sl-card-select"><input type="checkbox" data-lib-select="${E(asset.key)}" aria-label="选择${E(asset.name)}" ${selectedAssets.has(asset.key)?'checked':''}>选择</label>`:''}<a class="sl-asset-picture" href="#${assetURL(asset)}">${asset.image?`<img src="${E(asset.image)}" alt="${E(asset.name)}" loading="lazy">`:`<div><b>${{故事文本:'文',角色:'◎',场景:'▧',道具:'◇',声音:'♫',视频:'▷',角色模型:'⌘'}[asset.type]||'▨'}</b><small>${asset.placeholder?'说明占位':E(L.subcategoryOf(asset))}</small></div>`}<span>${E(L.categoryOf(asset))}</span></a><section><h3><a href="#${assetURL(asset)}">${E(asset.name)}</a></h3><p>${E(L.subcategoryOf(asset))} · ${E(sourceLabel(asset))}</p>${assetTagChips(asset)}<footer><small>${asset.placeholder?'说明占位':asset.pending?'待采用 · '+asset.versions.length+'个候选':asset.version?'已保存 · '+(asset.versions?.length||1)+'个版本':'设定待配图'}</small><span>${projects.length?'关联 '+projects.length+' 个项目'+(pendingOnly?' · 待采用':''):'未关联项目'}</span></footer></section></article>`;
  }
  function assets(ctx){const index=load(),key=ctx.params.get('item');if(key)return assetDetail(index.assets.find(asset=>asset.key===key),index);if(ctx.parts[2])return oldRoute(ctx);
    hydrateView(ctx,['assetType','assetTags','assetState','assetSource','assetProject','assetSearch']);
    if(ctx.params.has('project'))view.assetProject=ctx.params.get('project');if(ctx.params.has('source'))view.assetSource=ctx.params.get('source');if(ctx.params.get('type')==='scripts')view.assetType='故事文本';
    view.assetType=L.normalizeCategory(view.assetType);
    if(!types.includes(view.assetType))view.assetType='全部';
    const knownTags=new Set((index.meta.tags||[]).map(tag=>tag.id));
    view.assetTags=view.assetTags.split(',').filter(id=>id==='untagged'||knownTags.has(id)).join(',');
    const selectedType=view.assetType,project=view.assetProject,source=view.assetSource;
    const list=index.assets.filter(asset=>L.matchesAsset(asset,view));
    selectedAssets=new Set([...selectedAssets].filter(key=>list.some(asset=>asset.key===key)));
    const options=(items,selected)=>items.map(([key,label])=>`<option value="${E(key)}" ${selected===key?'selected':''}>${E(label)}</option>`).join('');
    return `<div class="sl-page">${heading('资产库','收纳你保存的创作成果与作品设定，可独立使用，也可按需用于项目。',a('去创作工具','/app/tools'))}${warning()}<div class="sl-toolbar"><div class="sl-tabs" role="group" aria-label="资产类型">${types.map(type=>b(type,'asset-type',type,selectedType===type?'selected':'ghost')).join('')}</div><label class="sl-search">⌕<input data-lib-search="assetSearch" aria-label="搜索资产" value="${E(view.assetSearch)}" placeholder="搜索角色、素材或设定"></label></div>${tagFilters(index)}<div class="sl-filter-row"><label>创作来源<select data-lib-filter="assetSource">${options([['all','全部来源'],...Object.entries(L.sourceLabels),...(source==='personal'?[['personal','个人资产（旧筛选）']]:[])],source)}</select></label><label>关联项目<select data-lib-filter="assetProject">${options([['all','全部资产'],['unlinked','未关联项目'],...index.projects.map(p=>[p.key,L.labels[p.kind]+' · '+p.title])],project)}</select></label><label>状态<select data-lib-filter="assetState">${options([['active','正常'],['trash','回收站']],view.assetState)}</select></label><span>${list.length} 项资产</span></div>${bulkTagBar(list)}<div class="sl-asset-grid">${list.map(assetCard).join('')||empty('没有符合条件的资产','试试其他筛选，或在创作工具保存成果。无需先创建项目。')}</div><p class="sl-footnote">工具成果可独立保存、预览和下载。用于项目时保留原成果，并记录所选版本；候选与采用状态可在详情中查看。</p></div>`;
  }
  function profileText(value){if(!value)return '';return Object.entries(value).filter(([key,value])=>!['id','assetId','aliases'].includes(key)&&typeof value==='string'&&value).map(([key,value])=>`<p><b>${E(({name:'姓名',identity:'身份',relation:'人物关系',state:'当前状态',intro:'人物介绍',traits:'性格特点',story:'角色经历',notes:'补充说明',role:'剧情角色',age:'年龄',gender:'性别',background:'经历背景',appearance:'外貌特征',personality:'性格',motivation:'人物动机'})[key]||'其他设定')}</b><br>${E(value)}</p>`).join('');}
  function assetDetail(asset,index){if(!asset)return `<div class="sl-page">${empty('未找到这项资产','来源工程和其他资产不会受到影响。')}${a('返回资产库','/app/assets')}</div>`;
    const owner=index.projects.find(p=>p.key===asset.owner),canUse=reusable(asset),chosen=index.assets.find(item=>item.key===asset.sourceAssetKey);
    const usageEntries=owner&&!asset.usages.some(use=>use.projectKey===owner.key)?[{projectKey:owner.key,label:owner.title,source:true},...asset.usages]:asset.usages;
    const gallery=Object.entries(asset.version?.images||{}).map(([slot,image])=>({slot,image:L.imageOf(image,owner?.kind==='comic')})).filter((item,i,items)=>item.image&&items.findIndex(other=>other.image===item.image)===i);
    const names={main:'主设定',portrait:'头像',front:'正面',side:'侧面',back:'背面',clothing:'服装参考',accessories:'配饰',expression:'表情参考'};
    return `<div class="sl-page">${backLink('/app/assets')}${heading(E(asset.name),L.subcategoryOf(asset)+' · '+sourceLabel(asset),toolActions(asset)+(asset.state==='active'&&asset.type==='故事文本'?(asset.raw.settingOnly?b('下载设定文本','download-setting',asset.key,'primary'):b('选用故事创作','use-story',asset.key,'primary')):canUse?b('用于作品','use-asset',asset.key,'primary'):'')+(asset.state==='trash'?b('恢复资产','restore-asset',asset.key):b('移入回收站','trash-asset',asset.key)))}${warning()}<section class="sl-detail-tags"><span>我的标签</span>${assetTagChips(asset)||'<small>未添加标签</small>'}${b('＋ 标签','edit-tags',asset.key)}</section>${asset.sourceUpdated?`<p class="sl-warning">来源有更新。当前作品仍使用保存的版本。${chosen&&asset.state==='active'?b('把来源新版加入候选','sync-source',asset.key):''}</p>`:''}<div class="sl-detail-grid"><div><section class="sl-panel"><h2>${asset.type==='故事文本'?'故事与分集':asset.type==='角色'?'人物与视觉设定':'内容预览'}</h2>${asset.placeholder?`<div class="sl-media-placeholder"><b>${asset.type==='声音'?'♫':'▷'}</b><h3>${E(asset.subtype)}占位</h3><p>${E(asset.description)}</p><small>本示例不生成或播放具体媒体。</small></div>`:asset.image?`<img class="sl-main-image" src="${E(asset.image)}" alt="${E(asset.name)}">`:asset.type==='声音'?`<div class="sl-media-placeholder"><b>♫</b><p>${E(asset.subtype)}</p><p>${E(asset.raw.notice||'已独立保存。点击上方「试听 / 下载」查看保存的声音，无需绑定项目。')}</p></div>`:''}<p class="sl-description">${E(asset.description)}</p>${asset.type==='故事文本'?(asset.raw.settingOnly?`<pre>${E(asset.original||asset.description)}</pre>`:asset.episodes.map(ep=>`<details><summary>${E(ep.title)}</summary><p>${E(ep.events)}</p><pre>${E(L.body(asset.raw.scripts?.[ep.id])||'本集尚无正文')}</pre></details>`).join('')):profileText(asset.profile)}${gallery.length>1?`<h3>整套参考</h3><div class="sl-gallery">${gallery.map(item=>`<figure><img src="${E(item.image)}" alt="${E(names[item.slot]||imageLabel(item.slot))}"><figcaption>${E(names[item.slot]||imageLabel(item.slot))}</figcaption></figure>`).join('')}</div>`:''}${asset.type==='角色'?`<h3>角色的其他设定</h3><p>服饰、表情姿势、音色和角色模型与人物一起关联，在项目中选择适合本作的版本。</p>${(asset.raw.voiceProfiles||[]).map(item=>`<div class="sl-setting-row">♫ ${E(item.title||item.name||'角色音色')} · 已保存音色方案</div>`).join('')}${(asset.raw.pngtuberRefs||[]).map(item=>`<div class="sl-setting-row">⌘ ${E(item.title||'PNGTuber')} · 四状态素材已关联</div>`).join('')}${(asset.raw.performanceRefs||[]).map(item=>`<div class="sl-setting-row">◎ ${E(item.title||'表情与姿势')} · ${(item.items||[]).length}项</div>`).join('')}${index.assets.filter(item=>item.parentAssetKey===asset.key).map(item=>a(E(item.name),assetURL(item))).join('')}`:''}</section><section class="sl-panel"><h2>版本与候选</h2>${asset.versions?.length?asset.versions.map((version,i)=>`<div class="sl-version"><div><strong>${E(version.label||'版本 '+(i+1))}</strong><small>${E(version.origin||asset.origin)}${version.librarySource?' · 来自其他作品或个人资产':''}</small></div>${Object.values(version.images||{}).some(Boolean)||version.image?b('预览','preview-version',asset.key+'|'+version.id):''}${asset.version?.id===version.id?tags(asset.owner&&asset.type!=='故事文本'?'当前采用':'已保存'):asset.state==='active'&&owner?.state==='active'&&['comic','video'].includes(owner.kind)&&['角色','场景','道具'].includes(asset.type)?b('采用此版本','adopt-version',asset.key+'|'+version.id):tags('历史记录')}</div>`).join(''):'<p>暂无参考版本，可继续进入原工作台完善。</p>'}${owner?a('在工作台继续调整',owner.url):asset.url?a('打开原工具',asset.url):''}</section></div><aside><section class="sl-panel"><h2>创作来源</h2><p>${E(sourceLabel(asset))}${asset.tool&&asset.raw.toolId?' · '+E(ToolCatalog.find(asset.raw.toolId)?.title||asset.raw.toolId):''}</p><p class="sl-footnote">${E(asset.origin||'个人保存')}</p>${owner?'<p>来源项目：'+a(E(owner.title),projectURL(owner))+'</p>':'<p>独立创作成果，无需绑定项目。</p>'}${chosen?`<p>引用自 ${a(E(chosen.name),assetURL(chosen))}</p>`:''}${asset.savedAt?`<p class="sl-footnote">保存于 ${E(new Date(asset.savedAt).toLocaleString('zh-CN'))}</p>`:''}<p class="sl-footnote">带入作品后独立保留所选版本，后续修改不会自动覆盖其他作品。</p>${asset.original?`<details><summary>保留的原文</summary><pre>${E(asset.original)}</pre></details>`:''}</section><section class="sl-panel"><h2>关联项目与使用位置</h2>${usageEntries.length?usageEntries.map(use=>{const p=index.projects.find(p=>p.key===use.projectKey),target=index.assets.find(item=>item.key===use.assetKey);return `<div class="sl-usage">${target?a(E((p?.title||use.label)+' · '+target.name),assetURL(target)):p?a(E(p.title),projectURL(p)):E(use.label)}<small>${use.source?'来源项目':use.candidate?'候选 · 待采用':'保存的使用版本'}${p&&p.state!=='active'?' · 工程已归档或回收':''}</small></div>`;}).join(''):'<p>未关联项目。你可以独立预览、下载或继续创作，之后再按需选用。</p>'}</section>${asset.tool&&asset.url?`<section class="sl-panel"><h2>继续处理</h2>${a('打开创作工具',asset.url)}<p class="sl-footnote">已保存成果是独立快照，重新编辑草稿不会改变本份记录。</p></section>`:''}</aside></div></div>`;
  }
  function eligible(asset){return !!asset.version&&!asset.placeholder&&['角色','场景','道具','图像'].includes(asset.type)&&!!(asset.image||asset.version.images?.main)&&!['表情包'].includes(asset.subtype)&&!['expressions','image-motion'].includes(asset.raw.toolId)&&asset.subtype!=='漫画成稿页';}
  function useDialog(asset,selected){const index=load(),choices=L.projectChoices(index,asset),project=choices.find(p=>p.key===selected)||choices[0];const targets=project?index.assets.filter(item=>item.state==='active'&&item.key!==asset.key&&item.owner===project.key&&(['角色','场景','道具'].includes(asset.type)?item.type===asset.type:['角色','场景','道具'].includes(item.type))):[];
    S.modal('用于作品 · '+asset.name,`<p>将当前保存版本加入指定位置，作为候选供你确认。${asset.sourceUpdated?'来源更新不会自动替换旧版本。':''}</p>${choices.length?`<label>目标作品<select id="sl-use-project" data-lib-use-project="${E(asset.key)}">${choices.map(item=>`<option value="${E(item.key)}" ${project?.key===item.key?'selected':''}>${L.labels[item.kind]} · ${E(item.title)}</option>`).join('')}</select></label><label>目标资产<select id="sl-use-target"><option value="">请选择要加入的位置</option>${targets.map(item=>`<option value="${E(item.key)}">${E(item.name)} · ${E(item.type)}</option>`).join('')}${['角色','场景','道具'].includes(asset.type)?`<option value="new">新建${E(asset.type)}：${E(asset.name)}</option>`:''}</select></label>`:'<p>还没有兼容的目标作品。请先创建漫画或视频工程。</p>'}<p class="sl-footnote">同名资产不会自动合并；请明确选择已有角色，或新建一个独立角色。</p>`,choices.length&&(targets.length||['角色','场景','道具'].includes(asset.type))?b('确认新增候选','confirm-use',asset.key,'primary').replace('<button ','<button disabled '):a('创建作品','/app/projects'));
  }
  function comicImage(value){if(/^comic-studio\//.test(value))value=value.slice(13);return value;}
  async function normalVersion(asset,comic){const version=copy(asset.version),sourceImages=version.images||{main:asset.image};version.id=S.id('library-visual');version.label=asset.name+' · 选用候选';version.origin='资产库选用';version.createdAt=new Date().toISOString();version.librarySource={assetKey:asset.key,versionId:asset.version.id,name:asset.name};version.images={};
    for(const [slot,raw] of Object.entries(sourceImages)){let image=L.imageOf(raw,asset.owner?.startsWith('comic:'));if(!image)continue;if(comic){image=comicImage(image);if(!/^(data:image\/(png|jpeg|webp);base64,|examples\/romance-two\/(?:(?:revision|josei)\/)?assets\/|\.\.\/comic-lab\/assets\/)/.test(image)){const response=await fetch(L.safeImage(raw));if(!response.ok)throw Error('参考图片读取失败');const blob=await response.blob();image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});}}
      version.images[slot]=image;
    }if(!version.images.main)throw Error('当前版本缺少可用主参考图');version.image=version.images.main;return version;
  }
  async function importAsset(asset,projectKey,targetKey){guard();const index=load(),project=index.projects.find(item=>item.key===projectKey),target=index.assets.find(item=>item.key===targetKey);
    if(!asset||!eligible(asset)||findAsset(asset.key)?.state!=='active')throw Error('来源资产不可用');if(!project||project.state!=='active'||project.kind==='story')throw Error('目标作品不可用');if(targetKey!=='new'&&(!target||target.state!=='active'||target.key===asset.key||!['角色','场景','道具'].includes(target.type)||target.owner!==projectKey))throw Error('请选择有效目标');
    if(target&&['角色','场景','道具'].includes(asset.type)&&target.type!==asset.type)throw Error('目标资产类型不兼容');
    if(target?.versions?.some(v=>v.librarySource?.assetKey===asset.key&&v.librarySource?.versionId===asset.version.id))return target.key;const version=await normalVersion(asset,project.kind==='comic');if(findProject(projectKey)?.state!=='active'||findAsset(asset.key)?.state!=='active'||(target&&findAsset(targetKey)?.state!=='active'))throw Error('来源或目标状态已改变，请重新选择');const kind=asset.type==='角色'?'角色':asset.type;
    if(project.kind==='comic'){const db=read(COMIC,{projects:[]}),p=db.projects.find(item=>item.id===project.id);let entity=p.assets.find(item=>item.id===target?.id);if(!entity){if(!['角色','场景','道具'].includes(kind))throw Error('请指定已有的目标资产');entity={id:S.id('library-asset'),name:asset.name,kind,stable:asset.description||'',reference:'',visualVersions:[],storyProfile:copy(asset.profile||{})};p.assets.push(entity);}entity.visualVersions??=[];entity.visualVersions.push(version);entity.librarySource??={assetKey:asset.key,versionId:asset.version.id};if(!ComicStudio.validProject(p))throw Error('候选超出漫画保存范围，未写入');store(COMIC,db);return 'comic:'+p.id+':'+entity.id;
    }
    const entry=project.entries.find(entry=>entry.hostId===target?.host)||project.entries[0];if(!entry)throw Error('请先进入视频工作台初始化资产');const engine=C.M.db.projects[project.id][entry.hostId],before=copy(engine.videoFlow.workspace.assets);
    try{let entity=engine.videoFlow.workspace.assets.find(item=>item.id===target?.id);if(!entity){entity={id:S.id('library-asset'),name:asset.name,kind:kind==='角色'?'人物':kind,candidates:[],adoptedId:null,storyProfile:copy(asset.profile||{})};engine.videoFlow.workspace.assets.push(entity);}entity.candidates??=[];entity.candidates.push({...version,scope:'video'});entity.librarySource??={assetKey:asset.key,versionId:asset.version.id};if(!S.save())throw Error('空间不足，未保存');return project.key+':'+entry.hostId+':'+entity.id;}catch(error){engine.videoFlow.workspace.assets=before;throw error;}
  }
  function adopt(key,versionId){guard();const asset=findAsset(key),project=asset&&findProject(asset.owner);if(!asset||asset.state!=='active'||project?.state!=='active'||!['角色','场景','道具'].includes(asset.type)||!asset.versions.some(v=>v.id===versionId))throw Error('该资产或版本不可采用');if(project.kind==='comic'){const db=read(COMIC,{projects:[]}),p=db.projects.find(p=>p.id===project.id),entity=p.assets.find(a=>a.id===asset.id);if(!entity)throw Error('请在漫画工作台采用此类成稿');ComicStudio.assetAdopt(p,entity,versionId);store(COMIC,db);}else{const entry=project.entries.find(item=>item.hostId===asset.host),engine=C.M.db.projects[project.id][entry.hostId],entity=engine.videoFlow.workspace.assets.find(a=>a.id===asset.id);if(!entity.candidates.some(v=>v.id===versionId))throw Error('版本不存在');const p=S.state.projects.find(item=>item.id===project.id),c=p.episodes.find(item=>item.id===entry.hostId);C.M.videoVisualAssets.adopt({p,c,e:engine},entity.id,versionId);}}
  function storyDialog(asset){S.modal('选用故事开始创作',`<p>${E(asset.name)} · 使用当前已保存故事，原文与人物事实一起保留。</p><label>使用范围<select id="sl-story-episode"><option value="">整部故事</option>${asset.episodes.map(ep=>`<option value="${E(ep.id)}">${E(ep.title)}${L.body(asset.raw.scripts?.[ep.id])?'':' · 尚无正文'}</option>`).join('')}</select></label><label>创作类型<select id="sl-story-kind"><option value="comic">漫画</option><option value="video">视频</option></select></label>`,b('创建关联作品','confirm-story',asset.key,'primary'));}
  function handoff(asset,episodeId,kind){guard();if(!asset||findAsset(asset.key)?.state!=='active')throw Error('来源故事不可用');const selected=asset.episodes.filter(ep=>!episodeId||ep.id===episodeId);if(!selected.length||selected.some(ep=>!L.body(asset.raw.scripts?.[ep.id]).trim()))throw Error('所选范围还没有完整正文，请先进入故事创作补充');if(kind==='comic'){const db=read(COMIC,{version:1,projects:[]});if(db.projects.length>=30)throw Error('漫画工程已达30份上限');const project=ScriptStudio.toComic(asset.raw,episodeId);if(!ComicStudio.validProject(project))throw Error('所选内容超出漫画保存范围');db.projects.push(project);db.active=project.id;store(COMIC,db);S.route(withBack('/app/comic?project='+q(project.id)));}else{const source=C.M.videoFlow.fromStory(asset.raw,episodeId),ctx=C.M.videoFlow.create(source,{title:asset.name,ratio:'16:9'});C.M.videoWorkspace.ensure(ctx);if(!S.save())throw Error('视频工程未能保存');S.route(withBack('/app/video?project='+q(ctx.p.id)+'&episode='+q(ctx.c.id)+'&stage=1'));}}
  function rename(project,name){guard();name=name.trim();if(!name)throw Error('名称不能为空');name=name.slice(0,60);if(project.kind==='story'||project.kind==='comic'){const key=project.kind==='story'?STORY:COMIC,db=read(key,{}),p=db.projects.find(p=>p.id===project.id);p.title=name;p.updatedAt=new Date().toISOString();store(key,db);}else{const p=S.state.projects.find(p=>p.id===project.id),before=copy(p),entries=project.entries.map(entry=>({w:entry.engine.videoFlow.workspace,title:entry.engine.videoFlow.workspace.title}));p.name=name;for(const entry of entries)entry.w.title=name;if(!S.save()){Object.assign(p,before);for(const entry of entries)entry.w.title=entry.title;throw Error('重命名未保存');}}}
  const oldRoute=C.route;C.route=ctx=>{if(ctx.parts[0]!=='app')return oldRoute(ctx);if(ctx.parts[1]==='projects'&&!ctx.params.has('legacy'))return projects(ctx);if(ctx.parts[1]==='assets'&&!ctx.params.has('legacy'))return assets(ctx);if(ctx.parts[1]==='tool-results'){const params=new URLSearchParams(ctx.params);if(!params.has('assetSource'))params.set('source','tools');return assets({...ctx,parts:['app','assets'],params});}return oldRoute(ctx);};
  const oldAfter=C.afterRender;C.afterRender=ctx=>{oldAfter(ctx);const managing=!!document.querySelector('.sl-page');document.body.classList.toggle('studio-library-page',managing);const workspaceKey=ctx.parts[1]+':'+ctx.params.get('project'),givenReturn=localPath(ctx.params.get('back'));if(!managing&&givenReturn)workbenchReturns.set(workspaceKey,givenReturn);const returnTo=givenReturn||workbenchReturns.get(workspaceKey);if(!managing&&returnTo){const main=document.querySelector('main');if(main&&!document.getElementById('sl-workbench-back'))main.insertAdjacentHTML('afterbegin','<div id="sl-workbench-back" class="sl-workbench-back">'+a('← 返回项目与资产',returnTo,'sl-back')+'</div>');}if(managing){requestAnimationFrame(()=>window.scrollTo(0,scrollPositions.get(location.hash.slice(1))||0));document.getElementById('ts-personal-link')?.remove();const asset=ctx.params.get('item')&&findAsset(ctx.params.get('item')),project=ctx.params.get('item')&&findProject(ctx.params.get('item'));if(project?.sourceUpdated)document.querySelector('.sl-heading')?.insertAdjacentHTML('afterend','<p class="sl-warning">来源有新版本。当前改编继续使用已保存内容，可进入关联来源核对；正文不会自动替换。</p>');if(asset){const entries=[...document.querySelectorAll('.sl-usage')],seen=new Set();entries.forEach(node=>{const label=node.textContent.trim();if(seen.has(label))node.remove();else seen.add(label);});}}};
  document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(!link||!document.querySelector('.sl-page'))return;const href=link.getAttribute('href');if(!href?.startsWith('#/app/'))return;scrollPositions.set(location.hash.slice(1),window.scrollY);if(link.classList.contains('sl-back'))return;const path=href.slice(1),[base,query]=path.split('?'),params=new URLSearchParams(query||'');if(!params.has('back')){params.set('back',location.hash.slice(1));link.setAttribute('href','#'+base+'?'+params);}},true);
  document.addEventListener('click',async event=>{const button=event.target.closest('[data-lib]');if(!button)return;const {lib:act,key}=button.dataset;event.preventDefault();try{
    switch(act){
      case 'project-type':view.projectType=key;S.route(filterURL());break;
      case 'asset-type':view.assetType=key;selectedAssets.clear();S.route(filterURL());break;
      case 'filter-tag':{const current=view.assetTags.split(',').filter(Boolean);view.assetTags=key==='all'?'':key==='untagged'?'untagged':(current.includes(key)?current.filter(id=>id!==key):[...current.filter(id=>id!=='untagged'),key]).join(',');selectedAssets.clear();S.route(filterURL());break;}
      case 'toggle-bulk':selectingAssets=!selectingAssets;selectedAssets.clear();S.render();break;
      case 'select-visible':selectedAssets=new Set([...document.querySelectorAll('[data-lib-select]')].map(node=>node.dataset.libSelect));S.render();break;
      case 'clear-selection':selectedAssets.clear();S.render();break;
      case 'edit-tags':tagEditor([key],'replace');break;
      case 'bulk-add-tags':case 'bulk-remove-tags':if(!selectedAssets.size)throw Error('请先选择资产');tagEditor([...selectedAssets],act==='bulk-add-tags'?'add':'remove');break;
      case 'save-tags':await saveTagEditor();break;
      case 'manage-tags':tagManager();break;
      case 'create-tag':{const name=document.getElementById('sl-new-tag').value;await mutateTags(value=>L.createTag(value,S.id('tag'),name));S.render();tagManager();break;}
      case 'rename-tag':tagRename(key);break;
      case 'confirm-rename-tag':{const name=document.getElementById('sl-tag-name').value;await mutateTags(value=>L.renameTag(value,key,name));S.render();tagManager();break;}
      case 'merge-tag':tagMerge(key);break;
      case 'confirm-merge-tag':{const target=document.getElementById('sl-merge-target').value;await mutateTags(value=>L.mergeTag(value,key,target));S.render();tagManager();break;}
      case 'delete-tag':{const tag=(meta().tags||[]).find(tag=>tag.id===key);if(!tag)throw Error('标签不存在');S.modal('删除标签',`<p>删除「${E(tag.name)}」会取消所有资产上的这个标记，资产及其项目引用保留。</p>`,b('确认删除标签','confirm-delete-tag',key,'primary'));break;}
      case 'confirm-delete-tag':await mutateTags(value=>L.deleteTag(value,key));S.render();tagManager();break;
      case 'toggle-examples':view.onlyExamples=!view.onlyExamples;S.route(filterURL());break;
      case 'create-project':S.modal('开始新的作品','<p>选择创作类型，进入对应工作台。</p><div class="sl-create-options">'+a('故事创作','/app/script?intent=new')+b('漫画创作','create-comic')+a('视频创作','/app/video')+'</div>');break;
      case 'create-comic':{guard();const raw=localStorage.getItem(COMIC),db=raw?ComicStudio.restore(raw):{version:1,projects:[],active:null};const project=ComicStudio.newProject(db);store(COMIC,db);S.close();S.route(withBack('/app/comic?project='+q(project.id)));break;}
      case 'open-tool-result':ToolStudio.openSaved(key);break;
      case 'rename-project':{const p=findProject(key);S.modal('重命名项目',`<label>项目名称<input id="sl-project-name" maxlength="60" value="${E(p.title)}"></label>`,b('保存名称','confirm-rename',key,'primary'));break;}
      case 'confirm-rename':rename(findProject(key),document.getElementById('sl-project-name').value);S.close();S.render();S.toast('名称已保存');break;
      case 'archive-project':case 'restore-project':guard();await changeMeta(value=>{value.projects[key]={...value.projects[key],state:act==='archive-project'?'archived':'active'};});S.render();S.toast(act==='archive-project'?'已归档，工程与资产保留':'工程已恢复');break;
      case 'trash-project':S.modal('移入项目回收站','<p>保留工程内容与资产，可随时恢复。关联作品继续使用各自保存的版本。</p>',b('确认移入回收站','confirm-trash-project',key,'primary'));break;
      case 'confirm-trash-project':guard();await changeMeta(value=>{value.projects[key]={...value.projects[key],state:'trash'};});S.close();S.route('/app/projects');break;
      case 'trash-asset':{const asset=findAsset(key);S.modal('移入资产回收站',`<p>这项资产用于 ${new Set(asset.usages.map(use=>use.projectKey)).size} 个作品。从资产库隐藏后，作品已经保存的版本和引用仍然保留。可在资产回收站恢复。</p>`,b('确认移入回收站','confirm-trash-asset',key,'primary'));break;}
      case 'confirm-trash-asset':case 'restore-asset':guard();await changeMeta(value=>{value.assets[key]={...value.assets[key],state:act==='restore-asset'?'active':'trash'};});S.close();S.render();break;
      case 'use-asset':{const asset=findAsset(key);if(!reusable(asset))throw Error('此成果暂不可用于作品');if(asset.tool&&key.startsWith('tool:'))ToolStudio.bringSaved(asset.id);else if(asset.raw?.market&&asset.type==='声音')ToolStudio.bringSaved(asset.key);else useDialog(asset);break;}
      case 'preview-version':{const at=key.lastIndexOf('|'),asset=findAsset(key.slice(0,at)),version=asset?.versions.find(v=>v.id===key.slice(at+1));if(!version)throw Error('版本不存在');const images=Object.entries(version.images||{main:version.image}).map(([slot,raw])=>({slot,src:L.imageOf(raw,asset.owner?.startsWith('comic:'))})).filter(v=>v.src);S.modal('候选预览 · '+asset.name,'<p>'+E(version.label||'保存版本')+'</p><div class="sl-gallery">'+images.map(v=>'<figure><img src="'+E(v.src)+'" alt="'+E(imageLabel(v.slot))+'"><figcaption>'+E(imageLabel(v.slot))+'</figcaption></figure>').join('')+'</div><p>预览不会改变已采用版本。</p>','',true);break;}
      case 'confirm-use':{button.disabled=true;const asset=findAsset(key),target=await importAsset(asset,document.getElementById('sl-use-project').value,document.getElementById('sl-use-target').value);S.close();S.route('/app/assets?item='+q(target)+'&back='+q(location.hash.slice(1)));S.toast('已新增候选，请确认是否采用');break;}
      case 'adopt-version':{const at=key.lastIndexOf('|');adopt(key.slice(0,at),key.slice(at+1));S.render();S.toast('已采用，其他作品仍使用各自保存的版本');break;}
      case 'sync-source':{const target=findAsset(key),source=findAsset(target.sourceAssetKey);await importAsset(source,target.owner,target.key);S.render();S.toast('来源新版已加入候选，请主动采用');break;}
      case 'download-setting':{const asset=findAsset(key);if(!asset||asset.state!=='active'||!asset.raw.settingOnly)throw Error('设定不可用');S.download(asset.original||asset.description,asset.name+'.txt','text/plain;charset=utf-8');break;}
      case 'use-story':storyDialog(findAsset(key));break;
      case 'confirm-story':handoff(findAsset(key),document.getElementById('sl-story-episode').value,document.getElementById('sl-story-kind').value);break;
      case 'examples':guard();button.disabled=true;await StudioLibraryExamples.load();S.route('/app/projects?guide=1');S.toast('管理示例已就绪，用户原有工程保留');break;
    }
  }catch(error){S.toast(error.message);button.disabled=false;}});
  document.addEventListener('change',event=>{const select=event.target;if(select.dataset.libSelect){if(select.checked)selectedAssets.add(select.dataset.libSelect);else selectedAssets.delete(select.dataset.libSelect);const counter=document.getElementById('sl-selected-count');if(counter)counter.textContent='已选择 '+selectedAssets.size+' 项';for(const button of document.querySelectorAll('[data-lib=bulk-add-tags],[data-lib=bulk-remove-tags]'))button.disabled=!selectedAssets.size;return;}if(select.dataset.libUseProject){useDialog(findAsset(select.dataset.libUseProject),select.value);return;}const field=select.dataset.libFilter;if(select.id==='sl-use-target'){const confirm=document.querySelector('[data-lib=confirm-use]');if(confirm)confirm.disabled=!select.value;return;}if(field){selectedAssets.clear();view[field]=select.value;S.route(filterURL());}});
  let searchTimer;document.addEventListener('input',event=>{const field=event.target.dataset.libSearch;if(!field)return;view[field]=event.target.value;const position=event.target.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(!document.querySelector('.sl-page'))return;S.route(filterURL());setTimeout(()=>{const input=document.querySelector(`[data-lib-search="${field}"]`);input?.focus();input?.setSelectionRange(position,position);},40);},180);});
  window.StudioLibrary={load,meta,store,changeMeta,importAsset,adopt,findAsset,findProject,KEY,STORY,COMIC,guard};
})();
